import{_ as e,o as a,c as t,a5 as o}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"HJ74 参数解析","description":"中等 通过率：29.16% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 在命令行输入如下命令： xcopy /s c:\\\\\\\\ d:\\\\\\\\e， 各个参数如下： 参数1：命令字xcopy 参数2：字符串/s 参数3：字符串c:\\\\\\\\ 参数4: 字符串d:\\\\\\\\e 请编写一个。","frontmatter":{"title":"HJ74 参数解析","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：29.16% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 在命令行输入如下命令： xcopy /s c:\\\\\\\\ d:\\\\\\\\e， 各个参数如下： 参数1：命令字xcopy 参数2：字符串/s 参数3：字符串c:\\\\\\\\ 参数4: 字符串d:\\\\\\\\e 请编写一个。","sidebarWeight":63,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ74 参数解析.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ74 参数解析.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ74 参数解析.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ74 参数解析.md"};function s(i,r,c,p,u,_){return a(),t("div",null,[...r[0]||(r[0]=[o('<div><h1 id="hj74-参数解析" tabindex="-1">HJ74 参数解析 <a class="header-anchor" href="#hj74-参数解析" aria-label="Permalink to &quot;HJ74 参数解析&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ74 参数解析”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：29.16% 时间限制：1秒 空间限制：32M 知识点==字符串====模拟== <strong>描述</strong> 在命令行输入如下命令： xcopy /s c:\\ d:\\e， 各个参数如下： 参数1：命令字xcopy 参数2：字符串/s 参数3：字符串c:\\ 参数4: 字符串d:\\e 请编写一个参数解析程序，实现将命令行各个参数解析出来。</p></blockquote><p>解析规则： 1.参数分隔符为空格 2.对于用&quot;&quot;包含起来的参数，如果中间有空格，不能解析为多个参数。比如在命令行输入xcopy /s &quot;C:\\program files&quot; &quot;d:&quot;时，参数仍然是4个，第3个参数应该是字符串C:\\program files，而不是C:\\program，注意输出参数时，需要将&quot;&quot;去掉，引号不存在嵌套情况。 3.参数不定长 4.输入由用例保证，不会出现不符合要求的输入 数据范围：字符串长度：1≤�≤1000 1≤<em>s</em>≤1000 进阶：时间复杂度：�(�) <em>O</em>(<em>n</em>) ，空间复杂度：�(�) <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 输入一行字符串，可以有空格 <strong>输出描述：</strong> 输出参数个数，分解后的参数，每个参数都独占一行 <strong>示例1</strong> 输入： xcopy /s c:\\ d:\\e ==复制== 输出： 4xcopy/sc:\\d:\\e</p><p>思路：</p><ul><li>当碰到引号时，进入一种新模式，然后其它判断以这个模式开关进行判断；</li><li>当在这个模式中碰到另外一个引号，处理数据，结束这个模式</li></ul><p>input_str = input().strip() # 去除输入字符串首尾的空格 args = [] # 初始化参数列表 current_arg = &quot;&quot; # 当前正在处理的参数 in_quotes = False # 是否在双引号内 for c in input_str: if c == &#39;&quot;&#39;: # 遇到双引号 in_quotes = not in_quotes # 切换双引号内外状态 continue # 不将双引号添加到参数中 if c.isspace() and not in_quotes: # 遇到空格，并且不在双引号内 if current_arg: # 如果当前参数非空，说明一个参数已经结束 args.append(current_arg) # 将这个参数加入到参数列表 current_arg = &quot;&quot; # 重置当前参数为空字符串，准备接收下一个参数 else: current_arg += c # 将字符添加到当前参数的末尾 if current_arg: # 最后一个参数后面可能没有空格，需要额外处理 args.append(current_arg) # 将最后一个参数添加到参数列表</p><h1 id="输出参数个数和每个参数" tabindex="-1">输出参数个数和每个参数 <a class="header-anchor" href="#输出参数个数和每个参数" aria-label="Permalink to &quot;输出参数个数和每个参数&quot;">​</a></h1><p>print(len(args)) for arg in args: print(arg)</p><p><strong>状态机解法</strong> 这次我们将使用一个状态机的思路，通过切换状态来识别参数： def parse_command(command): args = [] # 用于存储解析出来的参数 current_arg = [] # 用于构建当前参数 in_quotes = False # 标记是否处于引号内 for c in command: if c == &#39;&quot;&#39;: # 遇到引号，切换引号内外状态 in_quotes = not in_quotes elif c == &#39; &#39; and not in_quotes: # 遇到空格，且不在引号内 if current_arg: # 如果当前参数已经开始收集 args.append(&#39;&#39;.join(current_arg)) # 完成一个参数的收集，加入到参数列表 current_arg = [] # 重置当前参数为空列表，为收集新参数准备 else: current_arg.append(c) # 将字符加入当前参数 if current_arg: # 检查是否有未完成的参数 args.append(&#39;&#39;.join(current_arg)) # 将最后的参数加入到参数列表 return args</p><h1 id="读取命令行输入" tabindex="-1">读取命令行输入 <a class="header-anchor" href="#读取命令行输入" aria-label="Permalink to &quot;读取命令行输入&quot;">​</a></h1><p>command_line = input().strip()</p><h1 id="解析命令行" tabindex="-1">解析命令行 <a class="header-anchor" href="#解析命令行" aria-label="Permalink to &quot;解析命令行&quot;">​</a></h1><p>parsed_args = parse_command(command_line)</p><h1 id="打印解析结果" tabindex="-1">打印解析结果 <a class="header-anchor" href="#打印解析结果" aria-label="Permalink to &quot;打印解析结果&quot;">​</a></h1><p>print(len(parsed_args)) for arg in parsed_args: print(arg) 这个函数parse_command将命令行字符串作为输入，并返回参数列表。我们用一个列表current_arg来构建当前参数，这样可以避免在每次循环时创建新字符串，提高效率。当遇到引号时，我们切换in_quotes状态。当遇到空格且不在引号内时，我们将current_arg添加到参数列表中。如果遇到字符，我们则将其添加到current_arg。最后，如果在输入结束时current_arg非空，我们也将其添加到参数列表中。这样就可以保证正确解析出所有参数。 这种方法的好处是它在遍历输入字符串时立即构建参数，而无需回头检查或重新分配字符串，从而在大多数情况下提高了效率。</p></div>',1)])])}const g=e(n,[["render",s]]);export{l as __pageData,g as default};
